package password

import (
	"errors"

	"golang.org/x/crypto/bcrypt"
)

var ErrMismatchedHashAndPassword = errors.New("password: hash and password do not match")

func Hash(plaintext string) (string, error) {
	hashed, err := bcrypt.GenerateFromPassword([]byte(plaintext), bcrypt.DefaultCost)
	if err != nil {
		return "", err
	}
	return string(hashed), nil
}

func Verify(hash, plaintext string) error {
	if err := bcrypt.CompareHashAndPassword([]byte(hash), []byte(plaintext)); err != nil {
		if errors.Is(err, bcrypt.ErrMismatchedHashAndPassword) {
			return ErrMismatchedHashAndPassword
		}
		return err
	}
	return nil
}

package password

import (
	"errors"
	"testing"
)

func TestHashVerifyRoundTrip(t *testing.T) {
	hash, err := Hash("correct horse battery staple")
	if err != nil {
		t.Fatalf("Hash: %v", err)
	}
	if hash == "correct horse battery staple" {
		t.Fatal("hash must not equal the plaintext")
	}
	if err := Verify(hash, "correct horse battery staple"); err != nil {
		t.Fatalf("Verify: %v", err)
	}
}

func TestVerifyRejectsWrongPassword(t *testing.T) {
	hash, err := Hash("correct horse battery staple")
	if err != nil {
		t.Fatalf("Hash: %v", err)
	}
	if err := Verify(hash, "wrong password"); !errors.Is(err, ErrMismatchedHashAndPassword) {
		t.Fatalf("expected ErrMismatchedHashAndPassword, got %v", err)
	}
}

func TestHashUsesUniqueSalt(t *testing.T) {
	first, err := Hash("same password")
	if err != nil {
		t.Fatalf("Hash: %v", err)
	}
	second, err := Hash("same password")
	if err != nil {
		t.Fatalf("Hash: %v", err)
	}
	if first == second {
		t.Fatal("hashes of the same password must differ due to salting")
	}
}

package main

import (
	"fmt"
	"log"

	"example.com/cryptoapp/internal/password"
)

func main() {
	hash, err := password.Hash("correct horse battery staple")
	if err != nil {
		log.Fatalf("hash password: %v", err)
	}
	fmt.Println("hash:", hash)

	if err := password.Verify(hash, "correct horse battery staple"); err != nil {
		log.Fatalf("verify correct password: %v", err)
	}
	if err := password.Verify(hash, "wrong password"); err == nil {
		log.Fatal("verify wrong password: expected an error")
	}
	fmt.Println("password verified")
}
